#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemver.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE *alpha,
		 DATA_TYPE *beta,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(u1,N,n),
		 DATA_TYPE POLYBENCH_1D(v1,N,n),
		 DATA_TYPE POLYBENCH_1D(u2,N,n),
		 DATA_TYPE POLYBENCH_1D(v2,N,n),
		 DATA_TYPE POLYBENCH_1D(w,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  DATA_TYPE fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
    {
      u1[i] = i;
      u2[i] = ((i+1)/fn)/2.0;
      v1[i] = ((i+1)/fn)/4.0;
      v2[i] = ((i+1)/fn)/6.0;
      y[i] = ((i+1)/fn)/8.0;
      z[i] = ((i+1)/fn)/9.0;
      x[i] = 0.0;
      w[i] = 0.0;
      for (j = 0; j < n; j++)
        A[i][j] = (DATA_TYPE) (i*j % n) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(w,N,n))
{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("w");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, w[i]);
  }
  POLYBENCH_DUMP_END("w");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemver[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

  // Fuse Loop 1 and Loop 2.
  // We interchange Loop 2 to traverse rows in the outer loop, allowing fusion with Loop 1.
  // This bypasses a completely separate N^2 memory traversal and transforms 
  // Loop 2's cache-unfriendly column-major access into high-performance row-major access.
  // We unroll the outer loop by 8 to massively improve CPU register utility.
  for (i = 0; i < _PB_N - 7; i += 8) {
    DATA_TYPE u1_0 = u1[i], u1_1 = u1[i+1], u1_2 = u1[i+2], u1_3 = u1[i+3];
    DATA_TYPE u1_4 = u1[i+4], u1_5 = u1[i+5], u1_6 = u1[i+6], u1_7 = u1[i+7];

    DATA_TYPE u2_0 = u2[i], u2_1 = u2[i+1], u2_2 = u2[i+2], u2_3 = u2[i+3];
    DATA_TYPE u2_4 = u2[i+4], u2_5 = u2[i+5], u2_6 = u2[i+6], u2_7 = u2[i+7];

    DATA_TYPE y0 = y[i], y1 = y[i+1], y2 = y[i+2], y3 = y[i+3];
    DATA_TYPE y4 = y[i+4], y5 = y[i+5], y6 = y[i+6], y7 = y[i+7];

    #pragma GCC ivdep
    #pragma GCC unroll 8
    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE v1_j = v1[j];
      DATA_TYPE v2_j = v2[j];
      DATA_TYPE xj = x[j];

      // Computations structured to evaluate cleanly while perfectly matching original C scalar semantics.
      DATA_TYPE a0 = A[i][j] + u1_0 * v1_j + u2_0 * v2_j; 
      A[i][j] = a0; 
      xj += beta * a0 * y0;

      DATA_TYPE a1 = A[i+1][j] + u1_1 * v1_j + u2_1 * v2_j; 
      A[i+1][j] = a1; 
      xj += beta * a1 * y1;

      DATA_TYPE a2 = A[i+2][j] + u1_2 * v1_j + u2_2 * v2_j; 
      A[i+2][j] = a2; 
      xj += beta * a2 * y2;

      DATA_TYPE a3 = A[i+3][j] + u1_3 * v1_j + u2_3 * v2_j; 
      A[i+3][j] = a3; 
      xj += beta * a3 * y3;

      DATA_TYPE a4 = A[i+4][j] + u1_4 * v1_j + u2_4 * v2_j; 
      A[i+4][j] = a4; 
      xj += beta * a4 * y4;

      DATA_TYPE a5 = A[i+5][j] + u1_5 * v1_j + u2_5 * v2_j; 
      A[i+5][j] = a5; 
      xj += beta * a5 * y5;

      DATA_TYPE a6 = A[i+6][j] + u1_6 * v1_j + u2_6 * v2_j; 
      A[i+6][j] = a6; 
      xj += beta * a6 * y6;

      DATA_TYPE a7 = A[i+7][j] + u1_7 * v1_j + u2_7 * v2_j; 
      A[i+7][j] = a7; 
      xj += beta * a7 * y7;

      x[j] = xj;
    }
  }
  // Remainder for Pass 1 (Loop 1 & 2 Fusion) if `_PB_N` is not divisible by 8.
  for (; i < _PB_N; i++) {
    DATA_TYPE u1_i = u1[i];
    DATA_TYPE u2_i = u2[i];
    DATA_TYPE yi = y[i];
    #pragma GCC ivdep
    #pragma GCC unroll 8
    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE a = A[i][j] + u1_i * v1[j] + u2_i * v2[j];
      A[i][j] = a;
      x[j] += beta * a * yi;
    }
  }

  // Loop 3: Update `x`
  #pragma GCC ivdep
  #pragma GCC unroll 8
  for (i = 0; i < _PB_N; i++) {
    x[i] += z[i];
  }

  // Loop 4: Update `w`
  // We similarly unroll this parallel matrix accumulation loop over `i` by 8
  // to establish continuous multi-way stream utilization and minimize reads to arrays.
  for (i = 0; i < _PB_N - 7; i += 8) {
    // We prime standard variables exactly with existing references to strictly match
    // mathematically invariant execution operations and protect FP integrity.
    DATA_TYPE sum0 = w[i];
    DATA_TYPE sum1 = w[i+1];
    DATA_TYPE sum2 = w[i+2];
    DATA_TYPE sum3 = w[i+3];
    DATA_TYPE sum4 = w[i+4];
    DATA_TYPE sum5 = w[i+5];
    DATA_TYPE sum6 = w[i+6];
    DATA_TYPE sum7 = w[i+7];

    #pragma GCC ivdep
    #pragma GCC unroll 8
    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE xj = x[j];
      sum0 += alpha * A[i][j] * xj;
      sum1 += alpha * A[i+1][j] * xj;
      sum2 += alpha * A[i+2][j] * xj;
      sum3 += alpha * A[i+3][j] * xj;
      sum4 += alpha * A[i+4][j] * xj;
      sum5 += alpha * A[i+5][j] * xj;
      sum6 += alpha * A[i+6][j] * xj;
      sum7 += alpha * A[i+7][j] * xj;
    }

    w[i] = sum0;
    w[i+1] = sum1;
    w[i+2] = sum2;
    w[i+3] = sum3;
    w[i+4] = sum4;
    w[i+5] = sum5;
    w[i+6] = sum6;
    w[i+7] = sum7;
  }
  // Remainder for Loop 4.
  for (; i < _PB_N; i++) {
    DATA_TYPE sum = w[i];
    #pragma GCC ivdep
    #pragma GCC unroll 8
    for (j = 0; j < _PB_N; j++) {
      sum += alpha * A[i][j] * x[j];
    }
    w[i] = sum;
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(u1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(u2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(w, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(z, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(u1),
	      POLYBENCH_ARRAY(v1),
	      POLYBENCH_ARRAY(u2),
	      POLYBENCH_ARRAY(v2),
	      POLYBENCH_ARRAY(w),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y),
	      POLYBENCH_ARRAY(z));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemver (n, alpha, beta,
		 POLYBENCH_ARRAY(A),
		 POLYBENCH_ARRAY(u1),
		 POLYBENCH_ARRAY(v1),
		 POLYBENCH_ARRAY(u2),
		 POLYBENCH_ARRAY(v2),
		 POLYBENCH_ARRAY(w),
		 POLYBENCH_ARRAY(x),
		 POLYBENCH_ARRAY(y),
		 POLYBENCH_ARRAY(z));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(w)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(u1);
  POLYBENCH_FREE_ARRAY(v1);
  POLYBENCH_FREE_ARRAY(u2);
  POLYBENCH_FREE_ARRAY(v2);
  POLYBENCH_FREE_ARRAY(w);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(z);

  return 0;
}
