/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemver[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j, jj;

#pragma scop

  /* Block the inner loops to comfortably fit segments inside L1/L3 caches. 
     A 128 cache-blocking tile guarantees L1 hits for the local 1D variables. */
  for (jj = 0; jj < _PB_N; jj += 128) {
    int j_end = (jj + 128 < _PB_N) ? (jj + 128) : _PB_N;

    /* Pass 1: Fused updating of matrix A and vector x.
       The outer loop over 'i' is explicitly unrolled 8 times for Register blocking. */
    for (i = 0; i <= _PB_N - 8; i += 8) {
      /* Keep constant values spanning multiple j's loaded in CPU registers */
      DATA_TYPE u1_0 = u1[i+0], u1_1 = u1[i+1], u1_2 = u1[i+2], u1_3 = u1[i+3];
      DATA_TYPE u1_4 = u1[i+4], u1_5 = u1[i+5], u1_6 = u1[i+6], u1_7 = u1[i+7];

      DATA_TYPE u2_0 = u2[i+0], u2_1 = u2[i+1], u2_2 = u2[i+2], u2_3 = u2[i+3];
      DATA_TYPE u2_4 = u2[i+4], u2_5 = u2[i+5], u2_6 = u2[i+6], u2_7 = u2[i+7];

      DATA_TYPE by_0 = beta * y[i+0], by_1 = beta * y[i+1], by_2 = beta * y[i+2], by_3 = beta * y[i+3];
      DATA_TYPE by_4 = beta * y[i+4], by_5 = beta * y[i+5], by_6 = beta * y[i+6], by_7 = beta * y[i+7];

      #pragma GCC ivdep
      for (j = jj; j < j_end; j++) {
        DATA_TYPE v1_j = v1[j];
        DATA_TYPE v2_j = v2[j];
        DATA_TYPE xj = x[j];

        /* Update 8 independent row streams sequentially */
        DATA_TYPE a0 = A[i+0][j] + u1_0 * v1_j + u2_0 * v2_j;
        DATA_TYPE a1 = A[i+1][j] + u1_1 * v1_j + u2_1 * v2_j;
        DATA_TYPE a2 = A[i+2][j] + u1_2 * v1_j + u2_2 * v2_j;
        DATA_TYPE a3 = A[i+3][j] + u1_3 * v1_j + u2_3 * v2_j;
        DATA_TYPE a4 = A[i+4][j] + u1_4 * v1_j + u2_4 * v2_j;
        DATA_TYPE a5 = A[i+5][j] + u1_5 * v1_j + u2_5 * v2_j;
        DATA_TYPE a6 = A[i+6][j] + u1_6 * v1_j + u2_6 * v2_j;
        DATA_TYPE a7 = A[i+7][j] + u1_7 * v1_j + u2_7 * v2_j;

        A[i+0][j] = a0;
        A[i+1][j] = a1;
        A[i+2][j] = a2;
        A[i+3][j] = a3;
        A[i+4][j] = a4;
        A[i+5][j] = a5;
        A[i+6][j] = a6;
        A[i+7][j] = a7;

        /* Sequential addition avoids deep dependency graphs and optimizes for FMA instruction generation */
        xj += by_0 * a0;
        xj += by_1 * a1;
        xj += by_2 * a2;
        xj += by_3 * a3;
        xj += by_4 * a4;
        xj += by_5 * a5;
        xj += by_6 * a6;
        xj += by_7 * a7;

        x[j] = xj;
      }
    }
    /* Cleanup pass for Pass 1 when _PB_N is not cleanly divisible by 8 */
    for (; i < _PB_N; i++) {
      DATA_TYPE u1_i = u1[i];
      DATA_TYPE u2_i = u2[i];
      DATA_TYPE by_i = beta * y[i];

      #pragma GCC ivdep
      for (j = jj; j < j_end; j++) {
        DATA_TYPE a = A[i][j] + u1_i * v1[j] + u2_i * v2[j];
        A[i][j] = a;
        x[j] += by_i * a;
      }
    }

    /* Pass 2: Accumulate the finalized local vector tile of x with z */
    #pragma GCC ivdep
    for (j = jj; j < j_end; j++) {
      x[j] += z[j];
    }

    /* Pass 3: Process the fully accumulated tile of vector w.
       Similar 8-way explicit register unrolling scheme as Pass 1. */
    for (i = 0; i <= _PB_N - 8; i += 8) {
      DATA_TYPE w0 = w[i+0];
      DATA_TYPE w1 = w[i+1];
      DATA_TYPE w2 = w[i+2];
      DATA_TYPE w3 = w[i+3];
      DATA_TYPE w4 = w[i+4];
      DATA_TYPE w5 = w[i+5];
      DATA_TYPE w6 = w[i+6];
      DATA_TYPE w7 = w[i+7];

      #pragma GCC ivdep
      for (j = jj; j < j_end; j++) {
        DATA_TYPE ax = alpha * x[j];
        w0 += A[i+0][j] * ax;
        w1 += A[i+1][j] * ax;
        w2 += A[i+2][j] * ax;
        w3 += A[i+3][j] * ax;
        w4 += A[i+4][j] * ax;
        w5 += A[i+5][j] * ax;
        w6 += A[i+6][j] * ax;
        w7 += A[i+7][j] * ax;
      }

      w[i+0] = w0;
      w[i+1] = w1;
      w[i+2] = w2;
      w[i+3] = w3;
      w[i+4] = w4;
      w[i+5] = w5;
      w[i+6] = w6;
      w[i+7] = w7;
    }
    /* Cleanup pass for Pass 3 remainder */
    for (; i < _PB_N; i++) {
      DATA_TYPE wi = w[i];

      #pragma GCC ivdep
      for (j = jj; j < j_end; j++) {
        wi += alpha * A[i][j] * x[j];
      }
      w[i] = wi;
    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(u1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(u2, DATA_TYPE, N, n);
