  *alpha = 1.5;
  *beta = 1.2;

  DATA_TYPE fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
    {
      u1[i] = i;
      u2[i] = ((i+1)/fn)/2.0;
      v1[i] = ((i+1)/fn)/4.0;
      v2[i] = ((i+1)/fn)/6.0;
      y[i] = ((i+1)/fn)/8.0;
      z[i] = ((i+1)/fn)/9.0;
      x[i] = 0.0;
      w[i] = 0.0;
      for (j = 0; j < n; j++)
        A[i][j] = (DATA_TYPE) (i*j % n) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(w,N,n))
{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("w");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, w[i]);
  }
  POLYBENCH_DUMP_END("w");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemver[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
#pragma scop

  /* Enclose the computational logic in a single parallel region to minimize fork/join overhead. */
  #pragma omp parallel
  {
    /* 
     * Fused Loop 1 & 2: 
     * 1. A[i][j] is fully updated, and its contribution directly added into x[j].
     * 2. Tiled across columns (j0) by blocks of 32 elements. This provides sufficient
     *    independent OpenMP tasks while perfectly fitting the hot vectors (v1, v2, x)
     *    into the L1 data cache.
     * 3. Row loop (i) is unrolled by 4 to heavily amortize L1 reads of vector arrays
     *    and massively expose instruction level parallelism (ILP) for the FMA operations.
     */
    #pragma omp for schedule(dynamic)
    for (int j0 = 0; j0 < _PB_N; j0 += 32) {
      int j_end = (j0 + 32 > _PB_N) ? _PB_N : j0 + 32;
      int i = 0;

      for (; i <= _PB_N - 4; i += 4) {
        DATA_TYPE u1_0 = u1[i], u1_1 = u1[i+1], u1_2 = u1[i+2], u1_3 = u1[i+3];
        DATA_TYPE u2_0 = u2[i], u2_1 = u2[i+1], u2_2 = u2[i+2], u2_3 = u2[i+3];
        DATA_TYPE by0 = beta * y[i], by1 = beta * y[i+1], by2 = beta * y[i+2], by3 = beta * y[i+3];

        #pragma GCC ivdep
        for (int j = j0; j < j_end; j++) {
          DATA_TYPE v1j = v1[j];
          DATA_TYPE v2j = v2[j];
          DATA_TYPE xj = x[j];

          // Compute and apply iteration i
          DATA_TYPE a0 = A[i][j] + u1_0 * v1j + u2_0 * v2j;
          A[i][j] = a0;
          xj += by0 * a0;

          // Compute and apply iteration i+1
          DATA_TYPE a1 = A[i+1][j] + u1_1 * v1j + u2_1 * v2j;
          A[i+1][j] = a1;
          xj += by1 * a1;

          // Compute and apply iteration i+2
          DATA_TYPE a2 = A[i+2][j] + u1_2 * v1j + u2_2 * v2j;
          A[i+2][j] = a2;
          xj += by2 * a2;

          // Compute and apply iteration i+3
          DATA_TYPE a3 = A[i+3][j] + u1_3 * v1j + u2_3 * v2j;
          A[i+3][j] = a3;
          xj += by3 * a3;

          x[j] = xj;
        }
      }
      // Remainder logic for Fused Loop 1 & 2
      for (; i < _PB_N; i++) {
        DATA_TYPE u1_i = u1[i];
        DATA_TYPE u2_i = u2[i];
        DATA_TYPE by_i = beta * y[i];

        #pragma GCC ivdep
        for (int j = j0; j < j_end; j++) {
          DATA_TYPE a = A[i][j] + u1_i * v1[j] + u2_i * v2[j];
          A[i][j] = a;
          x[j] += by_i * a;
        }
      }
    }

    /* 
     * Loop 3: Add z into fully-computed x.
     * OpenMP provides an implicit synchronization barrier before moving onto this loop. 
     */
    #pragma omp for schedule(static)
    for (int i = 0; i < _PB_N; i++) {
      x[i] += z[i];
    }

    /* 
     * Loop 4: Standard Dense Matrix-Vector Multiplication (GEMV).
     * The `i` loop is similarly unrolled by 4 to hoist `alpha * x[j]` evaluation
     * and allow parallel accumulation across the 4 contiguous rows without redundant 
     * vector array memory traffic.
     */
    #pragma omp for schedule(dynamic)
    for (int i = 0; i < _PB_N - 3; i += 4) {
      DATA_TYPE sum0 = w[i];
      DATA_TYPE sum1 = w[i+1];
      DATA_TYPE sum2 = w[i+2];
      DATA_TYPE sum3 = w[i+3];

      #pragma GCC ivdep
      for (int j = 0; j < _PB_N; j++) {
        DATA_TYPE axj = alpha * x[j];
        sum0 += A[i][j] * axj;
        sum1 += A[i+1][j] * axj;
        sum2 += A[i+2][j] * axj;
        sum3 += A[i+3][j] * axj;
      }

      w[i] = sum0;
      w[i+1] = sum1;
      w[i+2] = sum2;
      w[i+3] = sum3;
    }

    /* Remainder for Loop 4 */
    #pragma omp single
    {
      for (int i = _PB_N - (_PB_N % 4); i < _PB_N; i++) {
        DATA_TYPE sum = w[i];

        #pragma GCC ivdep
        for (int j = 0; j < _PB_N; j++) {
          sum += A[i][j] * (alpha * x[j]);
        }

        w[i] = sum;
      }
    }
  }

#pragma endscop
}


